/* ======================================================================================
   SCENES: "The 20-20-60 Split" (SRT-timed). Every on-screen word traces to a cue in
   20-20-60.srt (see FLOW.md). Every scene boundary and every reveal is placed on the SRT clock:
   C[n-1] is the start of cue n. Transitions finish exactly on the cue that starts the scene.
   ====================================================================================== */
let SCENES = [], CUES = [], SFX_CUES = [], STORYBOARD = [];

/* SRT:BEGIN (generated by tools/srt_sync.py; do not edit by hand) */
const C = [0.0, 2.4, 4.9, 10.5, 13.8, 16.8, 21.5, 26.4, 29.6, 35.0, 39.8, 44.8, 48.0, 52.5, 58.0, 63.2, 68.5, 73.4, 78.4, 81.5, 85.8, 90.6, 96.2, 99.5, 103.686];
const SRT_TEXT = ["Idha konjam diagrammatic-ah explain panren.", "Idha 20-20-60 split-nu solluvaanga.", "Ippo oru category of people, adhaavadhu first 20 percentage of the people, Never Buy category-kulla varuvaanga.", "Ivanga yen inga irukkaanga-nu avangalukkum theriyaadhu, namakkum theriyaadhu.", "Ivangalukku need irukkaadhu, ivangalaala pay panna mudiyaadhu,", "and at the same time, ivangalukku namma idha evlo kashtappattu sell pannaalum, ivanga kandippaa vaanga maattaanga.", "So, ivangalukku namma efforts poduradhu-ndradhe waste of time. So, ivangalukku sales thevaiye kidaiyaadhu.", "And innoru 20 percentage of people, Definitely Buy.", "Ivanga eppadi-naa Amazon purchasers maadhiri. Ippo namma vandhu oru Amazon-la oru porul vaangurom appadinaa,", "ippo vaangurom—cart-la podrathu kidaiyaadhu—vaangurom appadinaa, oru porul venum-nu decide pannuvom, poi product-ah paappom,", "search pannuvom, description paappom, details nallaa irukkaa-nu paappom, features-laam nallaa irukkaa-nu paappom,", "paatthuttu nallaa irukkaa, purchase pannittu vandhutte iruppom.", "Adhe maadhiri dhaan ivangalum. Nammala patthi, namma website, namma enna sell panrom-ngradha patthi,", "and namma dhaan venum appadindra maadhiri ellaathaiyum paatthuttu, decide pannittu, nammakitta lead-ah vandhiruppaanga.", "So, ivangakitta product-oda features-ah kashtappattu sell pannanum appadindra maadhiri-laam oru avasiyamum kidaiyaadhu.", "Enna irukku, evlo-nu sonnaa podhum, kandippaa vaangirvaanga. Ivanga Definitely Buy category-kulla varuvaanga.", "Aanaa, innoru 60 percentage of people irukkaanga. Ivanga dhaan Confused Buyers.", "So, ivangalukku first indha product mela need irukkaa illaiyaa, yaarukitta vaanguradhu,", "and vaanginaa use pannuvaangalaa maattaangalaa,", "and ippo adhu avangalukku thevaiyaa illa future-la thevaiyaa, illa idhukku badhilaa avangalukku vera edhaavadhu thevaiyaa,", "indha maadhiri multiple confusions irukkum, and ivangalukku decision making-la oru help thevaippadum.", "And yaaraavadhu help pannaa mattum dhaan ivangalukku edhu thevai, thevai illai-ne decide panna mudiyum-ndra oru situation-la iruppaanga.", "Ivangalukkaaga dhaan sales appadindra oru vishayame exist aagudhu.", "Adhaavadhu, confusion-la irukkavangalukku clarity kodutthu, decision making-la help panradhukku."];
/* SRT:END */

const cue = n => C[n - 1];             // start of cue n (absolute seconds)
const GY = 860;                         // ground line
const TR = 0.7;                         // transition length; the incoming scene starts TR before its cue
// Spine object: one bar, 10 slots (1 figure = 10%), split 20 | 20 | 60
const BAR = { x: 260, w: 1400, h: 64 };
const SEG = [[0, 2], [2, 4], [4, 10]];  // slot ranges per group
const SLOT = i => BAR.x + 70 + 140 * i;
const GROUP = ['NEVER BUY', 'DEFINITELY BUY', 'CONFUSED BUYERS'];

/* ---------------- project-only drawing helpers ---------------- */
/** The spine bar. col: [c0,c1,c2] segment colours; p: build 0..1; nums: 0..1 numbers; lab: [a0,a1,a2] label alphas. */
function spineBar(g, p, col, nums = 1, lab = [0, 0, 0], o = {}) {
  if (p <= 0) return;
  const x0 = o.x ?? BAR.x, w = (o.w ?? BAR.w), y = o.y ?? GY, h = o.h ?? BAR.h, k = w / BAR.w;
  const ws = [0.2, 0.2, 0.6].map(f => f * w), sp = E.out(clamp(p));
  let x = x0;
  for (let s = 0; s < 3; s++) {
    const segP = prog(sp, s * 0.18, s * 0.18 + 0.55);
    if (segP > 0) fillPoly(g, rrectPoly(x + 4 * k, y, (ws[s] - 8 * k) * E.out(segP), h, 14 * k), col[s]);
    if (nums > 0 && segP >= 1) {
      g.save(); g.globalAlpha *= nums; g.font = font('head', Math.round(40 * k)); g.fillStyle = PAL.cream; g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillText(['20%', '20%', '60%'][s], x + ws[s] / 2, y + h / 2 + 2); g.restore();
    }
    if (lab[s] > 0 && !o.noLabels) subline(g, GROUP[s], x + ws[s] / 2, y + h + 52, lab[s], 0, { face: 'label', size: 30, align: 'center', color: col[s] === PAL.red ? PAL.red : PAL.ink });
    x += ws[s];
  }
}
/** Small corner reprise of the spine (top-right), one segment highlighted. */
function miniBar(g, focus, p, tagText) {
  if (p <= 0) return;
  fadeAlpha(g, E.out(p), () => {
    spineBar(g, 1, [0, 1, 2].map(i => i === focus ? PAL.red : rgba(PAL.ink, .85)), 1, [0, 0, 0], { x: 1300, y: 120, w: 480, h: 44, noLabels: true });
    if (tagText) subline(g, tagText, 1300 + 480 * [0.1, 0.3, 0.7][focus], 210, 1, 0, { face: 'label', size: 26, align: 'center', color: PAL.red });
  });
}
/** Screen prop (browser window): title bar in ink with cream title; body painted by fn(x, y, w, h). */
function browserWin(g, x, y, w, h, title, p, fn) {
  if (p <= 0) return;
  const q = E.back(clamp(p));
  popAt(g, x + w / 2, y + h / 2, q, () => {
    fillPoly(g, rrectPoly(x - 8, y - 8, w + 16, h + 16, 26), PAL.ink);
    fillPoly(g, rrectPoly(x, y + 56, w, h - 56, 18), PAL.cream);
    g.fillStyle = PAL.cream; [0, 1, 2].forEach(i => { g.beginPath(); g.arc(x + 30 + i * 28, y + 26, 8, 0, 7); g.fill(); });
    g.font = font('head', 30); g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(title, x + w / 2, y + 28);
    if (fn) fn(x, y + 56, w, h - 56);
  });
}
/** Checklist row: text, then a red tick badge drawing on at p. */
function checkRow(g, text, x, y, p, o = {}) {
  if (p <= 0) return;
  subline(g, text, x + 54, y + 13, prog(p, 0, .5), 0, { face: 'label', size: o.size || 34, color: PAL.ink });
  g.save(); g.beginPath(); g.arc(x + 20, y, 20, 0, 7); g.lineWidth = 4; g.strokeStyle = rgba(PAL.ink, .35); g.stroke(); g.restore();
  badge(g, x + 20, y, prog(p, .35, 1), 'tick', PAL.red, PAL.cream, 20);
}
/** A card with gray lines (a list of features) that can be crossed out. */
function featureCard(g, x, y, p, crossP) {
  if (p <= 0) return;
  popAt(g, x + 170, y + 120, E.back(clamp(p)), () => {
    fillPoly(g, rrectPoly(x, y, 340, 240, 22), PAL.cream);
    g.save(); tracePoly(g, rrectPoly(x, y, 340, 240, 22)); g.lineWidth = 6; g.strokeStyle = PAL.ink; g.stroke(); g.restore();
    g.font = font('head', 34); g.fillStyle = PAL.ink; g.textAlign = 'left'; g.fillText('FEATURES', x + 28, y + 58);
    for (let i = 0; i < 3; i++) { fillPoly(g, rrectPoly(x + 28, y + 92 + i * 44, 22, 22, 11), PAL.gray); fillPoly(g, rrectPoly(x + 66, y + 95 + i * 44, 220 - i * 40, 16, 8), rgba(PAL.gray, .6)); }
  });
  crossMark(g, x + 170, y + 120, 120, crossP, 20);
}
/** Deterministic tangle (a knot of confusion) with N points; untangles into a straight arrow shaft. */
const KN = 240;
function knotPts(cx, cy, r) {
  const o = [];
  for (let i = 0; i < KN; i++) { const a = i / (KN - 1) * Math.PI * 10, rr = r * (0.55 + 0.45 * Math.sin(a * 1.37 + 0.8));
    o.push([cx + Math.cos(a) * rr * 1.25, cy + Math.sin(a * 1.13) * rr * 0.8]); }
  return o;
}
function linePts(x0, x1, y) { const o = []; for (let i = 0; i < KN; i++) o.push([lerp(x0, x1, i / (KN - 1)), y]); return o; }

function buildScenes() {
  const W = CONFIG.width, H = CONFIG.height;
  const KNOT = knotPts(960, 430, 120), LINE = linePts(700, 1160, 430);

  SCENES = [
    /* 1. THE 20-20-60 SPLIT  (cues 1-3)  ten buyers -> the bar splits 20 | 20 | 60 -> first 20% = NEVER BUY */
    { id: 'split', start: 0, end: cue(4),
      camera: t => tween([[0, { x: 0, y: 30, z: 1.06 }], [2.2, { x: 0, y: 0, z: 1 }], [cue(3) + .4, { x: 0, y: 0, z: 1 }], [cue(3) + 2.4, { x: -540, y: 80, z: 1.3 }]], t),
      draw(g, t, T, c) {
        dotGrid(g, c);
        const red0 = prog(t, cue(3), cue(3) + .6);
        world(g, c, () => {
          groundLine(g, GY, prog(t, 0, .8));
          const col = [mix(0, 1, red0) > .5 ? PAL.red : PAL.ink, rgba(PAL.ink, 1 - .55 * red0), rgba(PAL.ink, 1 - .55 * red0)];
          spineBar(g, prog(t, cue(2), cue(2) + 1.2), col, prog(t, cue(2) + 1.0, cue(2) + 1.6), [prog(t, cue(3) + .3, cue(3) + 1.0), 0, 0]);
          for (let i = 0; i < 10; i++) {
            const x = SLOT(i), kf = [[.15 + i * .1, x - 1300], [2.0 + i * .06, x, E.out]];
            const g0 = i < 2, rest = g0 ? poseMix(POSES.stand, POSES.cross, E.inOut(prog(t, cue(3) + .4, cue(3) + 1.0))) : POSES.stand;
            const w = walker(kf, t, .75, rest, 1);
            const colr = g0 ? (red0 > .5 ? PAL.red : PAL.ink) : rgba(PAL.ink, 1 - .55 * red0);
            drawStickman(g, { x: w.x, y: GY, s: .75, pose: idle(w.pose, t, i), facing: w.facing, color: colr, expr: 'neutral' });
          }
        });
        subline(g, 'Let me explain it with a diagram', 960, 210, prog(t, .3, .9), prog(t, cue(2) - .3, cue(2)), { align: 'center', size: 44, color: PAL.gray, face: 'label' });
        fadeAlpha(g, 1 - prog(t, cue(3), cue(3) + .4), () => headline(g, 'THE 20-20-60 SPLIT', 960, 220, prog(t, cue(2), cue(2) + 1.1), { align: 'center', size: 96, red: [1] }));
        headline(g, '20% NEVER BUY', 140, 220, prog(t, cue(3) + .3, cue(3) + 1.3), { size: 92, red: [1, 2] });
      } },

    /* 2. NEVER BUY  (cues 4-7)  nobody knows why they're here; no need, can't pay; won't buy; sales not needed */
    { id: 'never', start: cue(4) - TR, end: cue(8), enter: { type: 'iris', x: 400, y: 640, dur: TR },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.08 }], [2.2, { x: 0, y: 0, z: 1 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(4) - TR; dotGrid(g, c);
        const hx = 620, usKf = [[cue(6), 1420], [cue(6) + 1.4, 1060, E.out]];
        world(g, c, () => {
          groundLine(g, GY, 1);
          // hero: a Never Buy buyer (red)
          let hp = POSES.stand;
          hp = poseMix(hp, POSES.shrug, E.inOut(prog(t, cue(4) + .1, cue(4) + .6)));
          hp = poseMix(hp, POSES.stop, E.inOut(prog(t, cue(5), cue(5) + .5)));
          hp = poseMix(hp, POSES.cross, E.inOut(prog(t, cue(6) + .6, cue(6) + 1.1)));
          const hexpr = t < cue(5) ? 'confused' : 'neutral';
          const hr = drawStickman(g, { x: hx, y: GY, s: 1.15, pose: idle(hp, t, 1), facing: 1, color: PAL.red, expr: hexpr });
          // us (ink): a salesperson, labelled US
          const uw = walker(usKf, t, 1.15, POSES.point, -1);
          let up = t < cue(6) ? poseMix(POSES.stand, POSES.shrug, E.inOut(prog(t, cue(4) + .5, cue(4) + 1.0))) : uw.pose;
          up = poseMix(up, POSES.slump, E.inOut(prog(t, cue(7) + .1, cue(7) + .7)));
          const ux = t < cue(6) ? 1420 : uw.x;
          const ur = drawStickman(g, { x: ux, y: GY, s: 1.15, pose: idle(up, t, 2), facing: -1, color: PAL.ink, expr: t > cue(7) ? 'sad' : (t < cue(5) ? 'confused' : 'neutral') });
          tag(g, 'US', ux, GY + 70, prog(t, cue(4) + .4, cue(4) + .8), { size: 30 });
          tag(g, 'NEVER BUY', hx, GY + 70, prog(t, cue(4) + .2, cue(4) + .6), { size: 30, bg: PAL.red });
          // cue 4: "?" for both of them
          const qOut = 1 - prog(t, cue(5) - .3, cue(5));
          [[hr, 1, cue(4) + .2], [ur, -1, cue(4) + .9]].forEach(([r, d, a]) => thoughtBubble(g, r.head[0] + 40 * d, r.head[1] - 40, r.head[0] + 150 * d, r.head[1] - 150, 64, prog(t, a, a + 1.0) * qOut, (g2, rr, q) => {
            g2.globalAlpha *= q; g2.font = font('head', 84); g2.fillStyle = PAL.red; g2.textAlign = 'center'; g2.textBaseline = 'middle'; g2.fillText('?', 0, 6); }));
          // cue 6: our pitch goes in, nothing comes back
          for (let k = 0; k < 3; k++) {
            const a = cue(6) + 1.3 + k * 1.1, p = prog(t, a, a + .5), fade = 1 - prog(t, a + .7, a + 1.0);
            if (p > 0 && fade > 0) fadeAlpha(g, fade, () => arrowOn(g, ux - 110, 560 + k * 40, hx + 120, 560 + k * 40, p, PAL.red, 8, .08 * (k - 1)));
          }
          crossMark(g, (hx + 1060) / 2, 590, 90, prog(t, cue(7) + .5, cue(7) + 1.1));
        });
        subline(g, '20% NEVER BUY', 140, 150, 1, 0, { face: 'label', size: 30, color: PAL.gray });
        const hA = (a, b) => 1 - prog(t, a, b);
        fadeAlpha(g, hA(cue(5) - .3, cue(5)), () => {
          headline(g, 'WHY ARE THEY HERE?', 140, 240, prog(t, cue(4) + .1, cue(4) + 1.0), { size: 84, red: [3] });
          subline(g, "They don't know.", 140, 312, prog(t, cue(4) + 1.2, cue(4) + 1.7), 0, { size: 40 });
          subline(g, "We don't know.", 140, 362, prog(t, cue(4) + 1.9, cue(4) + 2.4), 0, { size: 40 });
        });
        fadeAlpha(g, hA(cue(6) - .3, cue(6)), () => headline(g, "NO NEED. CAN'T PAY.", 140, 240, prog(t, cue(5) + .1, cue(5) + 1.0), { size: 84, red: [3] }));
        fadeAlpha(g, hA(cue(7) - .3, cue(7)), () => {
          headline(g, "THEY WON'T BUY", 140, 240, prog(t, cue(6) + .1, cue(6) + 1.0), { size: 84, red: [2] });
          subline(g, 'However hard we sell', 140, 312, prog(t, cue(6) + 1.2, cue(6) + 1.7), 0, { size: 40 });
        });
        headline(g, 'SALES? NOT NEEDED.', 140, 240, prog(t, cue(7) + .1, cue(7) + 1.0), { size: 84, red: [0] });
        subline(g, 'Our effort here = waste of time', 140, 312, prog(t, cue(7) + 1.4, cue(7) + 1.9), 0, { size: 40 });
      } },

    /* 3. DEFINITELY BUY  (cues 8-12)  like an Amazon buyer: decide -> see the product -> search ... features -> purchase */
    { id: 'definite', start: cue(8) - TR, end: cue(13), enter: { type: 'wipe', dur: TR },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.06 }], [2.2, { x: 0, y: 0, z: 1 }], [cue(11) - cue(8) + TR, { x: 0, y: 0, z: 1 }], [cue(11) - cue(8) + TR + 1.6, { x: 90, y: 30, z: 1.06 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(8) - TR; dotGrid(g, c);
        const SX = 960, SY = 300, SW = 760, SH = 520;
        world(g, c, () => {
          groundLine(g, GY, 1);
          const w = walker([[cue(8) + .1, -200], [cue(8) + 2.0, 560, E.out]], t, 1.15, POSES.stand, 1);
          let pose = w.pose;
          pose = poseMix(pose, POSES.think, E.inOut(prog(t, cue(9) + .8, cue(9) + 1.3)));
          pose = poseMix(pose, POSES.point, E.inOut(prog(t, cue(10) + .6, cue(10) + 1.1)));
          pose = poseMix(pose, POSES.reach, E.inOut(prog(t, cue(12) + .1, cue(12) + .5)));
          pose = poseMix(pose, POSES.cheer, E.inOut(prog(t, cue(12) + 1.0, cue(12) + 1.5)));
          drawStickman(g, { x: w.x, y: GY, s: 1.15, pose: idle(pose, t, 3), facing: 1, color: PAL.red, expr: t > cue(12) + 1.0 ? 'happy' : 'neutral' });
          browserWin(g, SX, SY, SW, SH, 'AMAZON', prog(t, cue(9) + .2, cue(9) + .8), (x, y, w2, h2) => {
            const rows = [['DECIDE: I WANT IT', cue(10) + .2], ['SEE THE PRODUCT', cue(10) + 2.4], ['SEARCH', cue(11) + .1], ['DESCRIPTION', cue(11) + 1.1], ['DETAILS', cue(11) + 2.4], ['FEATURES', cue(11) + 3.6]];
            rows.forEach(([s, a], i) => checkRow(g, s, x + 40, y + 46 + i * 60, prog(t, a, a + .6), { size: 32 }));
            const bp = prog(t, cue(12) + .1, cue(12) + .6);
            if (bp > 0) popAt(g, x + w2 - 190, y + h2 - 62, E.back(bp), () => {
              fillPoly(g, rrectPoly(x + w2 - 330, y + h2 - 100, 280, 76, 38), PAL.red);
              g.font = font('head', 34); g.fillStyle = PAL.cream; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('PURCHASE', x + w2 - 190, y + h2 - 60);
            });
            badge(g, x + w2 - 60, y + h2 - 130, prog(t, cue(12) + 1.0, cue(12) + 1.6), 'tick', PAL.ink, PAL.cream, 30);
          });
        });
        miniBar(g, 1, prog(t, cue(8) + .4, cue(8) + 1.0));
        fadeAlpha(g, 1 - prog(t, cue(9) - .3, cue(9)), () => headline(g, '20% DEFINITELY BUY', 140, 240, prog(t, cue(8) + .1, cue(8) + 1.1), { size: 84, red: [1, 2] }));
        headline(g, 'LIKE AN AMAZON BUYER', 140, 240, prog(t, cue(9) + .1, cue(9) + 1.1), { size: 72, red: [2], maxW: 760 });
        subline(g, 'Really buying, not just adding to cart', 140, 400, prog(t, cue(10) + .1, cue(10) + .6), prog(t, cue(12) - .3, cue(12)), { size: 34 });
        subline(g, 'Looks good → purchase → done', 140, 400, prog(t, cue(12) + .6, cue(12) + 1.1), 0, { size: 34, face: 'label', color: PAL.red });
      } },

    /* 4. THEY COME TO US AS A LEAD  (cues 13-16)  about us, what we sell -> lead -> no feature selling -> what + how much -> buy */
    { id: 'lead', start: cue(13) - TR, end: cue(17), enter: { type: 'iris', x: 1340, y: 560, dur: TR },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.08 }], [2.2, { x: 0, y: 0, z: 1 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(13) - TR; dotGrid(g, c);
        world(g, c, () => {
          groundLine(g, GY, 1);
          browserWin(g, 150, 380, 560, 400, 'OUR WEBSITE', prog(t, cue(13) + .1, cue(13) + .6) * (1 - prog(t, cue(15) - .5, cue(15))), (x, y) => {
            checkRow(g, 'ABOUT US', x + 40, y + 70, prog(t, cue(13) + 1.0, cue(13) + 1.6));
            checkRow(g, 'WHAT WE SELL', x + 40, y + 150, prog(t, cue(13) + 2.6, cue(13) + 3.2));
            checkRow(g, 'DECIDED ON US', x + 40, y + 230, prog(t, cue(14) + .4, cue(14) + 1.0));
          });
          // the buyer walks from our website to us
          const w = walker([[cue(14) + 1.6, 860], [cue(14) + 3.8, 1180, E.out]], t, 1.1, POSES.stand, 1);
          let pose = poseMix(w.pose, POSES.think, E.inOut(prog(t, cue(13) + .4, cue(13) + .9)) * (1 - prog(t, cue(14) + 1.0, cue(14) + 1.5)));
          pose = poseMix(pose, POSES.cheer, E.inOut(prog(t, cue(16) + 2.6, cue(16) + 3.1)));
          const hr = drawStickman(g, { x: w.x, y: GY, s: 1.1, pose: idle(pose, t, 4), facing: t < cue(14) + 1.2 ? -1 : 1, color: PAL.red, expr: t > cue(14) + .9 ? 'happy' : 'neutral' });
          tag(g, 'LEAD', w.x, hr.head[1] - 110, prog(t, cue(14) + 3.6, cue(14) + 4.1) * (1 - prog(t, cue(16) - .3, cue(16))), { bg: PAL.red, size: 40 });
          // us
          let up = poseMix(POSES.stand, POSES.stop, E.inOut(prog(t, cue(15) + .2, cue(15) + .7)));
          up = poseMix(up, POSES.point, E.inOut(prog(t, cue(16), cue(16) + .5)));
          const ur = drawStickman(g, { x: 1560, y: GY, s: 1.1, pose: idle(up, t, 5), facing: -1, color: PAL.ink, expr: t > cue(16) + 2.6 ? 'happy' : 'neutral' });
          tag(g, 'US', 1560, GY + 70, prog(t, cue(13) + .3, cue(13) + .7), { size: 30 });
          featureCard(g, 220, 440, prog(t, cue(15) + .2, cue(15) + .7) * (1 - prog(t, cue(16) - .3, cue(16))), prog(t, cue(15) + 2.0, cue(15) + 2.8));
          speechBubble(g, 'WHAT IT IS', 1500, 320, ur.head[0] - 30, ur.head[1] - 20, prog(t, cue(16) + .2, cue(16) + .6), { size: 34 });
          speechBubble(g, 'HOW MUCH', 1250, 410, ur.head[0] - 60, ur.head[1] - 30, prog(t, cue(16) + 1.4, cue(16) + 1.8), { size: 34 });
          badge(g, hr.head[0] - 110, hr.head[1] - 30, prog(t, cue(16) + 3.0, cue(16) + 3.6), 'tick', PAL.red, PAL.cream, 34);
        });
        miniBar(g, 1, 1);
        const hA = (a, b) => 1 - prog(t, a, b);
        fadeAlpha(g, hA(cue(14) + 2.0, cue(14) + 2.3), () => {
          headline(g, 'SAME WITH US', 140, 240, prog(t, cue(13) + .1, cue(13) + 1.0), { size: 84, red: [2] });
          subline(g, 'They check everything about us', 140, 312, prog(t, cue(13) + 1.2, cue(13) + 1.7), 0, { size: 40 });
        });
        fadeAlpha(g, hA(cue(15) - .3, cue(15)), () => headline(g, 'THEY COME AS A LEAD', 140, 240, prog(t, cue(14) + 2.3, cue(14) + 3.2), { size: 80, red: [4] }));
        fadeAlpha(g, hA(cue(16) - .3, cue(16)), () => headline(g, 'NO NEED TO SELL FEATURES', 140, 240, prog(t, cue(15) + .1, cue(15) + 1.0), { size: 72, red: [4], maxW: 1150 }));
        headline(g, "THEY'LL SURELY BUY", 140, 240, prog(t, cue(16) + .1, cue(16) + 1.0), { size: 80, red: [1] });
        subline(g, 'Just say what it is and how much', 140, 312, prog(t, cue(16) + .5, cue(16) + 1.0), 0, { size: 40 });
        tag(g, 'DEFINITELY BUY', 960, 990, prog(t, cue(16) + 3.6, cue(16) + 4.1), { size: 34 });
      } },

    /* 5. CONFUSED BUYERS  (cues 17-20)  the bar returns; the 60% light up; their five questions */
    { id: 'confused', start: cue(17) - TR, end: cue(21), enter: { type: 'wipe', dur: TR },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.05 }], [2.0, { x: 0, y: 0, z: 1 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(17) - TR; dotGrid(g, c);
        const r6 = prog(t, cue(17), cue(17) + .6);
        world(g, c, () => {
          groundLine(g, GY, 1);
          spineBar(g, 1, [rgba(PAL.gray, .9), rgba(PAL.gray, .9), r6 > .5 ? PAL.red : PAL.ink], 1, [1, 1, prog(t, cue(17) + .3, cue(17) + 1.0)]);
          const heads = [];
          for (let i = 0; i < 10; i++) {
            const conf = i >= 4, base = [POSES.shrug, POSES.think][i % 2];
            const pose = conf ? poseMix(POSES.stand, base, E.inOut(prog(t, cue(17) + .4 + (i - 4) * .1, cue(17) + 1.0 + (i - 4) * .1))) : POSES.stand;
            const r = drawStickman(g, { x: SLOT(i), y: GY, s: .75, pose: idle(pose, t, i), facing: i % 2 ? -1 : 1,
              color: conf ? (r6 > .5 ? PAL.red : PAL.ink) : rgba(PAL.gray, .9), expr: conf && t > cue(17) + .5 ? 'confused' : 'neutral' });
            heads.push(r.head);
          }
          const Q = [['Do I need it?', 760, 470, 4, cue(18) + .1], ['Buy it from whom?', 1180, 360, 6, cue(18) + 2.6],
                     ['Will I use it?', 1590, 470, 8, cue(19) + .1], ['Now or later?', 1000, 560, 5, cue(20) + .1], ['Or something else?', 1460, 580, 9, cue(20) + 2.1]];
          Q.forEach(([s, x, y, i, a]) => speechBubble(g, s, x, y, heads[i][0], heads[i][1] - 30, prog(t, a, a + .45), { size: 32 }));
        });
        headline(g, '60% CONFUSED BUYERS', 140, 220, prog(t, cue(17) + .1, cue(17) + 1.1), { size: 84, red: [1, 2] });
      } },

    /* 6. WHY SALES EXISTS  (cues 21-24)  a knot of confusions -> help arrives -> knot straightens -> clarity, decision */
    { id: 'clarity', start: cue(21) - TR, end: cue(25), enter: { type: 'iris', x: 1180, y: 460, dur: TR },
      camera: t => tween([[0, { x: 0, y: 0, z: 1.08 }], [2.2, { x: 0, y: 0, z: 1 }]], t),
      draw(g, t0, T, c) {
        const t = t0 + cue(21) - TR; dotGrid(g, c);
        const un = E.inOut(prog(t, cue(23) + .4, cue(23) + 1.8)), clear = t > cue(24) + .4;
        world(g, c, () => {
          groundLine(g, GY, 1);
          for (let i = 0; i < 6; i++) {
            const base = [POSES.shrug, POSES.think][i % 2];
            const pose = poseMix(base, i % 2 ? POSES.cheer : POSES.stand, E.inOut(prog(t, cue(24) + .4 + i * .08, cue(24) + 1.0 + i * .08)));
            drawStickman(g, { x: 640 + i * 128, y: GY, s: .8, pose: idle(pose, t, i), facing: i < 3 ? 1 : -1, color: PAL.red, expr: clear ? 'happy' : 'confused' });
          }
          // the knot of confusions -> a straight line ending in an arrow head
          const dp = prog(t, cue(21) + .1, cue(21) + 1.6);
          const pts = KNOT.map((p, i) => mix(p, LINE[i], un));
          if (dp > 0) strokeOn(g, pts, un > 0 ? 1 : dp, PAL.ink, 8);
          if (un >= 1) { const hp = prog(t, cue(23) + 1.8, cue(23) + 2.2); strokeOn(g, [[1126, 400], [1160, 430], [1126, 460]], hp, PAL.ink, 8); }
          // us: help arrives
          const w = walker([[cue(22) + .2, 2100], [cue(22) + 2.0, 1620, E.out]], t, 1.15, POSES.reach, -1);
          const up = poseMix(w.pose, POSES.point, E.inOut(prog(t, cue(23) + .2, cue(23) + .6)));
          if (t > cue(22)) drawStickman(g, { x: w.x, y: GY, s: 1.15, pose: idle(up, t, 7), facing: -1, color: PAL.ink, expr: 'happy' });
          tag(g, 'US', w.x, GY + 70, prog(t, cue(22) + 1.8, cue(22) + 2.2), { size: 30 });
          tag(g, 'CLARITY', 960, 360, prog(t, cue(24) + .1, cue(24) + .6), { size: 44, bg: PAL.red });
          tag(g, 'DECISION', 1330, 430, prog(t, cue(24) + 1.4, cue(24) + 1.9), { size: 36 });
        });
        const hA = (a, b) => 1 - prog(t, a, b);
        fadeAlpha(g, hA(cue(22) - .3, cue(22)), () => {
          headline(g, 'SO MANY CONFUSIONS', 140, 220, prog(t, cue(21) + .1, cue(21) + 1.0), { size: 84, red: [2] });
          subline(g, 'They need help to decide', 140, 292, prog(t, cue(21) + 2.0, cue(21) + 2.5), 0, { size: 40 });
        });
        fadeAlpha(g, hA(cue(23) - .3, cue(23)), () => {
          headline(g, 'ONLY WITH HELP', 140, 220, prog(t, cue(22) + .1, cue(22) + 1.0), { size: 84, red: [2] });
          subline(g, 'can they decide what they need', 140, 292, prog(t, cue(22) + 1.4, cue(22) + 1.9), 0, { size: 40 });
        });
        headline(g, 'THIS IS WHY SALES EXISTS', 140, 220, prog(t, cue(23) + .1, cue(23) + 1.1), { size: 80, red: [3] });
        subline(g, 'Clarity for the confused. Help to decide.', 140, 292, prog(t, cue(24) + .8, cue(24) + 1.3), 0, { size: 40 });
        miniBar(g, 2, prog(t, cue(24) + 2.0, cue(24) + 2.6), 'SALES');
      } },
  ];

  STORYBOARD = [
    { t: 1.6, title: 'Cue 1: buyers walk in' },
    { t: cue(3) - .3, title: 'Cue 2: the bar splits 20 | 20 | 60' },
    { t: cue(4) - .5, title: 'Cue 3: first 20% = Never Buy' },
    { t: cue(5) - .4, title: 'Cue 4: why are they here?' },
    { t: cue(7) - .5, title: 'Cues 5-6: no need, can\'t pay, won\'t buy' },
    { t: cue(8) - .8, title: 'Cue 7: sales not needed' },
    { t: cue(9) - .3, title: 'Cue 8: 20% Definitely Buy' },
    { t: cue(12) - .3, title: 'Cues 9-11: like an Amazon buyer' },
    { t: cue(13) - .8, title: 'Cue 12: purchase, done' },
    { t: cue(14) + 1.0, title: 'Cue 13: our website, about us' },
    { t: cue(15) - .6, title: 'Cue 14: they come as a lead' },
    { t: cue(16) - .4, title: 'Cue 15: no need to sell features' },
    { t: cue(17) - .8, title: 'Cue 16: what + how much → buy' },
    { t: cue(18) - .4, title: 'Cue 17: 60% confused buyers' },
    { t: cue(21) - .8, title: 'Cues 18-20: their five questions' },
    { t: cue(22) - .4, title: 'Cue 21: so many confusions' },
    { t: cue(23) - .4, title: 'Cue 22: help arrives' },
    { t: cue(25) - .3, title: 'Cues 23-24: why sales exists' },
  ];
  MUSIC.accents = [cue(2), cue(3), cue(8), cue(12), cue(17), cue(23), cue(24)];
  SFX_CUES = [];
  CUES = SRT_TEXT.map((text, i) => ({ start: C[i], end: C[i + 1], text }));
}
